  {if ui_t(ui_eq($v_surface, 'panel'))}
    {capture $c_1}
      {foreach ui_l($v_stats) as $v_stat}
        {=ui_include('blocks/stat-figure.latte', ['p' => ['stat' => $v_stat, 'item' => $v_item, 'align' => $v_align]])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_cols, '2')) ? '2' : (ui_t(ui_eq($v_cols, '3')) ? '2-3' : (ui_t(ui_eq($v_cols, '4')) ? '2-4' : '3-6')))), 'Class' => ui_s(ui_cnv(['w-full items-center bg-muted px-6', ui_preset('blocks/presets/defaults.json', ['stats', 'panel'])])), 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_1])|noescape}
  {else}
    {capture $c_2}
      {foreach ui_l($v_stats) as $v_stat}
        {=ui_include('blocks/stat-figure.latte', ['p' => ['stat' => $v_stat, 'item' => $v_item, 'align' => $v_align]])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'stack')) ? '1' : (ui_t(ui_eq($v_cols, '2')) ? '2' : (ui_t(ui_eq($v_cols, '3')) ? '2-3' : (ui_t(ui_eq($v_cols, '4')) ? '2-4' : '3-6'))))), 'Class' => 'gap-6', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_2])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'align' => $v_align, 'measure' => (ui_t(ui_eq($v_surface, 'panel')) ? 'fill' : (ui_t(ui_eq($v_layout, 'stack')) ? 'xs' : 'default')), 'className' => ui_cnv([ui_cnv([ui_cnv([(ui_t(ui_eq($v_surface, 'image')) ? 'bg-transparent' : ''), (ui_t(ui_eq($v_surface, 'panel')) ? 'py-0' : '')]), (ui_t(ui_eq((ui_t(ui_eq($v_surface, 'image')) ? 'image' : 'none'), 'image')) ? 'relative isolate overflow-hidden' : '')])]), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_3])|noescape}
